def rollback_from_manifest(path: Path | str, expected_sha256: str, *, fault_hook: FaultHook | None = None) -> dict[str, Any]:
    """按完整 manifest hash guard 恢复三个角色并重开核对。"""

    manifest_path = Path(path).resolve()
    try:
        manifest_bytes = manifest_path.read_bytes()
    except OSError as exc:
        raise CanvasFailure(
            "missing_target", "rollback", f"rollback manifest cannot be read: {exc}", operation="rollback", target_path=str(path)
        ) from exc
    full_hash = __import__("hashlib").sha256(manifest_bytes).hexdigest()
    if full_hash != expected_sha256:
        raise CanvasFailure(
            "rollback_drift",
            "rollback",
            f"rollback manifest hash differs: expected {expected_sha256}, got {full_hash}",
            operation="rollback",
            target_path=str(path),
        )
    try:
        manifest = json.loads(manifest_bytes.decode("utf-8"))
        validate_instance("canvas-rollback-manifest.schema.json", manifest)
    except (UnicodeError, json.JSONDecodeError, SchemaValidationError) as exc:
        raise CanvasFailure(
            "invalid_request", "rollback", f"rollback manifest is invalid: {exc}", operation="rollback", target_path=str(path)
        ) from exc
    normalized = json.loads(json.dumps(manifest))
    normalized["guard"]["expected_manifest_content_sha256"] = "0" * 64
    content_hash = __import__("hashlib").sha256(canonical_json_bytes(normalized)).hexdigest()
    if content_hash != manifest["guard"]["expected_manifest_content_sha256"]:
        raise CanvasFailure(
            "rollback_drift", "rollback", "rollback manifest content guard differs", operation="rollback", target_path=str(path)
        )

    staging_root = Path(manifest["authorized_staging_root"]).resolve(strict=True)
    backup_root = resolve_scoped_path(staging_root, manifest["backup_root"], False)
    role_paths = {
        "canvas": resolve_scoped_path(staging_root, manifest["generated"]["canvas"]["path"], False),
        "validation_manifest": resolve_scoped_path(
            staging_root, manifest["generated"]["validation_manifest"]["path"], False
        ),
        "rollback_manifest": resolve_scoped_path(staging_root, manifest["rollback_manifest_path"], False),
    }
    expected_current = {
        "canvas": manifest["guard"]["expected_canvas_sha256"],
        "validation_manifest": manifest["guard"]["expected_validation_sha256"],
        "rollback_manifest": expected_sha256,
    }
    before_canvas = _rollback_state(role_paths["canvas"])
    for role in ROLE_ORDER:
        current = _rollback_state(role_paths[role])
        expected = {"state": "present", "sha256": expected_current[role]}
        if not _same_state(current, expected):
            raise CanvasFailure(
                "rollback_drift",
                "rollback",
                f"current {role} is not the generated role",
                operation="rollback",
                target_path=str(role_paths["canvas"]),
                before=before_canvas,
                after=current if role == "canvas" else before_canvas,
                changed=role == "canvas" and not _same_state(before_canvas, current),
            )

    backups: dict[str, bytes] = {}
    for role in ROLE_ORDER:
        baseline = manifest["baseline"][role]
        if baseline["state"] == "present":
            backup_path = resolve_scoped_path(backup_root, baseline["backup_path"], True)
            if sha256_file(backup_path) != baseline["backup_sha256"]:
                raise CanvasFailure(
                    "rollback_drift",
                    "rollback",
                    f"backup hash differs for {role}",
                    operation="rollback",
                    target_path=str(role_paths["canvas"]),
                    before=before_canvas,
                    after=before_canvas,
                )
            backups[role] = backup_path.read_bytes()

    try:
        for role in ROLE_ORDER:
            _call_hook(fault_hook, "rollback-ready", role)
            baseline = manifest["baseline"][role]
            if baseline["state"] == "absent":
                if sha256_file(role_paths[role]) != expected_current[role]:
                    raise CanvasFailure(
                        "rollback_drift",
                        "rollback",
                        f"{role} changed during rollback",
                        operation="rollback",
                        target_path=str(role_paths["canvas"]),
                        before=before_canvas,
                        after=_rollback_state(role_paths["canvas"]),
                    )
                role_paths[role].unlink()
            else:
                _atomic_copy_bytes(role_paths[role], backups[role], f"rollback-{role}", fault_hook)
        for role in ROLE_ORDER:
            actual = _rollback_state(role_paths[role])
            expected = manifest["baseline"][role]
            expected_state = {"state": expected["state"]}
            if expected["state"] == "present":
                expected_state["sha256"] = expected["sha256"]
            if not _same_state(actual, expected_state):
                raise OSError(f"rollback verification failed for {role}")
        if backup_root.exists():
            shutil.rmtree(backup_root)
    except CanvasFailure:
        raise
    except OSError as exc:
        raise CanvasFailure(
            "io_failure",
            "rollback",
            f"rollback I/O failed: {exc}",
            operation="rollback",
            target_path=str(role_paths["canvas"]),
            before=before_canvas,
            after=_rollback_state(role_paths["canvas"]),
            changed=not _same_state(before_canvas, _rollback_state(role_paths["canvas"])),
        ) from exc
    return {
        "schema_version": 1,
        "status": "passed",
        "operation": "rollback",
        "exit_code": 0,
        "manifest_path": str(manifest_path),
        "target_state": {
            "path": str(role_paths["canvas"]),
            "before": before_canvas,
            "after": _rollback_state(role_paths["canvas"]),
            "changed": not _same_state(before_canvas, _rollback_state(role_paths["canvas"])),
        },
        "roles_verified": 3,
    }

def aggregate_benchmark(
    *,
    contract_path: Path,
    corpus_path: Path,
    arm_a_path: Path,
    arm_b_path: Path,
    read_only_before_path: Path,
    read_only_after_path: Path,
) -> dict[str, Any]:
    contract = validate_contract(load_object(contract_path, "contract"))
    corpus = load_object(corpus_path, "corpus")
    conservative = _validate_arm(load_object(arm_a_path, "arm_a"), "arm_a")
    fanout = _validate_arm(load_object(arm_b_path, "arm_b"), "arm_b")
    read_only_guard = _read_only_guard(
        load_object(read_only_before_path, "read-only-before"),
        load_object(read_only_after_path, "read-only-after"),
    )
    expected_context_bytes = _context_bytes(corpus)
    if fanout["aggregate"]["reported_generation_context_bytes"] != expected_context_bytes:
        raise FanoutError("GENERATION_CONTEXT_COST_DRIFT", str(expected_context_bytes))
    output_bytes = _generated_output_bytes(conservative, fanout)
    if fanout["aggregate"]["reported_generated_output_bytes"] != output_bytes:
        raise FanoutError("GENERATED_OUTPUT_COST_DRIFT", str(output_bytes))
    conservative_pages = {item["path"] for item in conservative["page_files"]}
    fanout_pages = {item["path"] for item in fanout["page_files"]}
    aggregate_a = conservative["aggregate"]
    aggregate_b = fanout["aggregate"]
    comparison = {
        "median_navigation_step_reduction": round(aggregate_a["median_navigation_steps"] - aggregate_b["median_navigation_steps"], 6),
        "answer_accuracy_delta": round(aggregate_b["answer_accuracy"] - aggregate_a["answer_accuracy"], 6),
        "source_entailment_rate_delta": round(aggregate_b["source_entailment_rate"] - aggregate_a["source_entailment_rate"], 6),
        "page_increment": len(fanout_pages - conservative_pages),
        "page_removal": len(conservative_pages - fanout_pages),
        "page_increment_ratio_to_conservative": round(len(fanout_pages - conservative_pages) / len(conservative_pages), 6),
        "generation_context_bytes": expected_context_bytes,
        "generated_output_bytes": output_bytes,
    }
    threshold_sets = contract["recommendation_thresholds"]
    production_checks = _checks(threshold_sets["production_candidate"], comparison, aggregate_b)
    experiment_checks = _checks(threshold_sets["continue_experiment"], comparison, aggregate_b)
    if all(item["passed"] for item in production_checks):
        recommendation = "production-candidate"
        deciding_checks = production_checks
    elif all(item["passed"] for item in experiment_checks):
        recommendation = "continue-experiment"
        deciding_checks = experiment_checks
    else:
        recommendation = threshold_sets["fallback"]
        deciding_checks = experiment_checks
    records_a = {item["task_id"]: item for item in conservative["records"]}
    records_b = {item["task_id"]: item for item in fanout["records"]}
    if set(records_a) != set(records_b):
        raise FanoutError("TASK_SET_DRIFT", f"arm_a={sorted(records_a)} arm_b={sorted(records_b)}")
    tasks = [
        {
            "task_id": task_id,
            "category": records_a[task_id]["category"],
            "conservative": records_a[task_id],
            "fanout": records_b[task_id],
        }
        for task_id in sorted(records_a)
    ]
    return {
        "schema_version": 1,
        "status": "passed",
        "scope": "isolated-page-fanout-benchmark",
        "baseline_commit": contract["baseline_commit"],
        "read_only_guard": read_only_guard,
        "arms": {
            "conservative": {"arm_id": "arm_a", "aggregate": aggregate_a},
            "fanout": {"arm_id": "arm_b", "aggregate": aggregate_b},
        },
        "comparison": comparison,
        "threshold_evaluation": {
            "production_candidate": production_checks,
            "continue_experiment": experiment_checks,
            "deciding_checks": deciding_checks,
        },
        "recommendation": recommendation,
        "recommendation_reasons": [item for item in deciding_checks if not item["passed"]],
        "tasks": tasks,
    }

def execute(arguments: argparse.Namespace) -> dict[str, object]:
    if arguments.command == "generate":
        return generate_fanout(
            contract_path=arguments.contract,
            corpus_path=arguments.corpus,
            source_root=arguments.source_root,
            conservative_root=arguments.conservative_root,
            output_root=arguments.out,
            rollback_manifest=arguments.rollback_manifest,
            workspace_root=arguments.workspace_root,
        )
    if arguments.command == "rollback":
        return rollback_fanout(arguments.manifest, arguments.workspace_root)
    if arguments.command == "judge":
        result = judge_arm(
            judge_contract_path=arguments.judge_contract,
            projection_root=arguments.projection_root,
            source_root=arguments.source_root,
        )
        output = arguments.out.resolve()
        workspace = arguments.workspace_root.resolve()
        from .contracts import atomic_write_json, ensure_within

        atomic_write_json(ensure_within(output, workspace, "out"), result)
        return {**result, "output": str(output)}
    if arguments.command == "snapshot-read-only":
        result = snapshot_read_only(arguments.root)
        output = arguments.out.resolve()
        workspace = arguments.workspace_root.resolve()
        from .contracts import atomic_write_json, ensure_within

        atomic_write_json(ensure_within(output, workspace, "out"), result)
        return {**result, "output": str(output)}
    if arguments.command == "aggregate":
        result = aggregate_benchmark(
            contract_path=arguments.contract,
            corpus_path=arguments.corpus,
            arm_a_path=arguments.arm_a,
            arm_b_path=arguments.arm_b,
            read_only_before_path=arguments.read_only_before,
            read_only_after_path=arguments.read_only_after,
        )
        output = arguments.out.resolve()
        workspace = arguments.workspace_root.resolve()
        from .contracts import atomic_write_json, ensure_within

        atomic_write_json(ensure_within(output, workspace, "out"), result)
        return {**result, "output": str(output)}
    raise AssertionError(arguments.command)

class FanoutError(ValueError):
    def __init__(self, reason: str, detail: str) -> None:
        super().__init__(f"{reason}: {detail}")
        self.reason = reason
        self.detail = detail

def engine_identity(expected_version: str) -> dict[str, Any]:
    try:
        version = importlib.metadata.version("fastembed")
        numpy_version = importlib.metadata.version("numpy")
        onnxruntime_version = importlib.metadata.version("onnxruntime")
    except importlib.metadata.PackageNotFoundError as error:
        raise EngineUnavailable(f"embedding engine dependency is missing: {error.name}") from error
    if version != expected_version:
        raise EngineUnavailable(f"fastembed version drift: expected {expected_version}, actual {version}")
    return {
        "fastembed": version,
        "numpy": numpy_version,
        "onnxruntime": onnxruntime_version,
    }

def documents_digest(documents: list[dict[str, str]]) -> str:
    encoded = json.dumps(documents, ensure_ascii=False, sort_keys=True, separators=(",", ":"))
    return hashlib.sha256(encoded.encode("utf-8")).hexdigest()

def index_size_accounting(index_dir: Path, protocol: dict[str, Any]) -> dict[str, int]:
    manifest_path = index_dir / "index-manifest.json"
    manifest = json_load(manifest_path)
    if "index_bytes" in manifest:
        raise ValueError("index manifest must not contain the self-referential index_bytes field")
    payload_names = [name for name in protocol["index"]["files"] if name != manifest_path.name]
    payload_bytes = sum((index_dir / name).stat().st_size for name in payload_names)
    if int(manifest.get("payload_bytes", -1)) != payload_bytes:
        raise ValueError("index manifest payload bytes differ from final payload files")
    manifest_bytes = manifest_path.stat().st_size
    return {
        "index_payload_bytes": payload_bytes,
        "index_manifest_bytes": manifest_bytes,
        "index_bytes": payload_bytes + manifest_bytes,
    }
